     1	import { SignJWT, jwtVerify } from "jose";
     2	import bcrypt from "bcryptjs";
     3	
     4	const SESSION_COOKIE = "idealog_session";
     5	const SESSION_TTL_SECONDS = 60 * 60 * 24 * 30; // 30 days
     6	
     7	function getSecretKey() {
     8	  const secret = process.env.JWT_SECRET;
     9	  if (!secret || secret.length < 16) {
    10	    throw new Error("JWT_SECRET is not set or is too short");
    11	  }
    12	  return new TextEncoder().encode(secret);
    13	}
    14	
    15	export type SessionPayload = {
    16	  sub: string;
    17	  email: string;
    18	};
    19	
    20	export async function hashPassword(password: string): Promise<string> {
    21	  return bcrypt.hash(password, 12);
    22	}
    23	
    24	export async function verifyPassword(
    25	  password: string,
    26	  hash: string
    27	): Promise<boolean> {
    28	  return bcrypt.compare(password, hash);
    29	}
    30	
    31	export async function createSessionToken(payload: SessionPayload): Promise<string> {
    32	  return new SignJWT({ email: payload.email })
    33	    .setProtectedHeader({ alg: "HS256" })
    34	    .setSubject(payload.sub)
    35	    .setIssuedAt()
    36	    .setExpirationTime(`${SESSION_TTL_SECONDS}s`)
    37	    .sign(getSecretKey());
    38	}
    39	
    40	export async function verifySessionToken(
    41	  token: string
    42	): Promise<SessionPayload | null> {
    43	  try {
    44	    const { payload } = await jwtVerify(token, getSecretKey());
    45	    if (typeof payload.sub !== "string" || typeof payload.email !== "string") {
    46	      return null;
    47	    }
    48	    return { sub: payload.sub, email: payload.email };
    49	  } catch {
    50	    return null;
    51	  }
    52	}
    53	
    54	export { SESSION_COOKIE, SESSION_TTL_SECONDS };
