     1	import { DIMENSIONS } from "@/lib/scoring";
     2	import type { IdeaDTO } from "@/lib/types";
     3	
     4	export type Calibration = {
     5	  count: number;
     6	  avgTotalDelta: number;
     7	  perDimension: Array<{
     8	    key: (typeof DIMENSIONS)[number]["key"];
     9	    label: string;
    10	    avgDelta: number;
    11	  }>;
    12	};
    13	
    14	export function computeCalibration(ideas: IdeaDTO[]): Calibration | null {
    15	  const withHindsight = ideas.filter((i) => i.hindsightTotal != null);
    16	  if (withHindsight.length === 0) return null;
    17	
    18	  const perDimension = DIMENSIONS.map((d) => {
    19	    const diffs = withHindsight.map((i) => {
    20	      const hindsight = i[d.hKey] as number | null;
    21	      const predicted = i[d.key] as number;
    22	      return (hindsight ?? predicted) - predicted;
    23	    });
    24	    const avgDelta = diffs.reduce((a, b) => a + b, 0) / diffs.length;
    25	    return { key: d.key, label: d.label, avgDelta };
    26	  });
    27	
    28	  const avgTotalDelta =
    29	    withHindsight.reduce((sum, i) => sum + (i.delta ?? 0), 0) / withHindsight.length;
    30	
    31	  return { count: withHindsight.length, avgTotalDelta, perDimension };
    32	}
