     1	export type PredictionScores = {
     2	  differentiation: number;
     3	  evidence: number;
     4	  cost: number;
     5	  reversibility: number;
     6	};
     7	
     8	export type HindsightScores = {
     9	  hDifferentiation: number | null;
    10	  hEvidence: number | null;
    11	  hCost: number | null;
    12	  hReversibility: number | null;
    13	};
    14	
    15	export const DIMENSIONS = [
    16	  { key: "differentiation", hKey: "hDifferentiation", label: "Differentiation" },
    17	  { key: "evidence", hKey: "hEvidence", label: "Evidence" },
    18	  { key: "cost", hKey: "hCost", label: "Cost" },
    19	  { key: "reversibility", hKey: "hReversibility", label: "Reversibility" },
    20	] as const;
    21	
    22	export function totalScore(scores: PredictionScores): number {
    23	  return (
    24	    scores.differentiation + scores.evidence + scores.cost + scores.reversibility
    25	  );
    26	}
    27	
    28	export function hindsightTotal(scores: HindsightScores): number | null {
    29	  const { hDifferentiation, hEvidence, hCost, hReversibility } = scores;
    30	  if (
    31	    hDifferentiation == null ||
    32	    hEvidence == null ||
    33	    hCost == null ||
    34	    hReversibility == null
    35	  ) {
    36	    return null;
    37	  }
    38	  return hDifferentiation + hEvidence + hCost + hReversibility;
    39	}
    40	
    41	export function scoreDelta(
    42	  scores: PredictionScores & HindsightScores
    43	): number | null {
    44	  const hindsight = hindsightTotal(scores);
    45	  if (hindsight == null) return null;
    46	  return hindsight - totalScore(scores);
    47	}
