=== lib/session.ts
     1	import { cookies } from "next/headers";
     2	import { cache } from "react";
     3	import {
     4	  SESSION_COOKIE,
     5	  SESSION_TTL_SECONDS,
     6	  createSessionToken,
     7	  verifySessionToken,
     8	  type SessionPayload,
     9	} from "./auth";
    10	import { prisma } from "./prisma";
    11	
    12	export async function setSessionCookie(payload: SessionPayload) {
    13	  const token = await createSessionToken(payload);
    14	  const store = await cookies();
    15	  store.set(SESSION_COOKIE, token, {
    16	    httpOnly: true,
    17	    secure: process.env.NODE_ENV === "production",
    18	    sameSite: "lax",
    19	    path: "/",
    20	    maxAge: SESSION_TTL_SECONDS,
    21	  });
    22	}
    23	
    24	export async function clearSessionCookie() {
    25	  const store = await cookies();
    26	  store.delete(SESSION_COOKIE);
    27	}
    28	
    29	// Cached per-request: safe to call getSession() many times in one render pass.
    30	export const getSession = cache(async (): Promise<SessionPayload | null> => {
    31	  const store = await cookies();
    32	  const token = store.get(SESSION_COOKIE)?.value;
    33	  if (!token) return null;
    34	  return verifySessionToken(token);
    35	});
    36	
    37	export const getCurrentUser = cache(async () => {
    38	  const session = await getSession();
    39	  if (!session) return null;
    40	  const user = await prisma.user.findUnique({ where: { id: session.sub } });
    41	  return user;
    42	});
