     3	import { useState } from "react";
     4	import { Button, Input } from "@/components/ui";
     5	
     6	export function ShareControl({
     7	  ideaId,
     8	  shareToken,
     9	  onChange,
    10	}: {
    11	  ideaId: string;
    12	  shareToken: string | null;
    13	  onChange: (shareToken: string | null) => void;
    14	}) {
    15	  const [loading, setLoading] = useState(false);
    16	  const [copied, setCopied] = useState(false);
    17	
    18	  const url =
    19	    shareToken && typeof window !== "undefined"
    20	      ? `${window.location.origin}/s/${shareToken}`
    21	      : shareToken
    22	      ? `/s/${shareToken}`
    23	      : null;
    24	
    25	  async function enable(regenerate = false) {
    26	    setLoading(true);
    27	    const res = await fetch(`/api/ideas/${ideaId}/share`, {
    28	      method: "POST",
    29	      headers: { "Content-Type": "application/json" },
    30	      body: JSON.stringify({ regenerate }),
    31	    });
    32	    setLoading(false);
    33	    if (res.ok) {
    34	      const data = await res.json();
    35	      onChange(data.idea.shareToken);
    36	      setCopied(false);
    37	    }
    38	  }
    39	
    40	  async function disable() {
    41	    setLoading(true);
    42	    const res = await fetch(`/api/ideas/${ideaId}/share`, { method: "DELETE" });
    43	    setLoading(false);
    44	    if (res.ok) {
    45	      onChange(null);
    46	    }
    47	  }
    48	
    49	  async function copy() {
    50	    if (!url) return;
    51	    await navigator.clipboard.writeText(url);
    52	    setCopied(true);
    53	    setTimeout(() => setCopied(false), 1500);
    54	  }
    55	
    56	  if (!shareToken) {
    57	    return (
    58	      <div className="flex items-center justify-between gap-3">
    59	        <p className="text-sm text-muted">
    60	          Not shared. Anyone with the link can view this idea without an account.
    61	        </p>
    62	        <Button variant="secondary" size="sm" onClick={() => enable(false)} disabled={loading}>
    63	          {loading ? "Creating…" : "Create share link"}
    64	        </Button>
    65	      </div>
    66	    );
    67	  }
    68	
    69	  return (
    70	    <div className="space-y-2">
    71	      <div className="flex gap-2">
    72	        <Input readOnly value={url ?? ""} className="font-mono text-xs" />
    73	        <Button variant="secondary" size="sm" onClick={copy}>
    74	          {copied ? "Copied" : "Copy"}
    75	        </Button>
    76	      </div>
    77	      <div className="flex gap-2">
    78	        <Button variant="ghost" size="sm" onClick={() => enable(true)} disabled={loading}>
    79	          Rotate link
    80	        </Button>
    81	        <Button variant="danger" size="sm" onClick={disable} disabled={loading}>
    82	          Revoke access
    83	        </Button>
    84	      </div>
    85	    </div>
    86	  );
    87	}
